add('01_004',2.5,'16:9，女主席脸与包扎肩臂的中近景，脸居画面中央偏左，枕头向左右铺开；镜头停在床边眼高，胸口柔白遮映随原构图占下缘。','女主席闭着眼，眉尖略向上聚，嘴唇小幅张开吐出一口气；头陷在枕中，肩部随着呼吸很轻地起伏，长发贴着枕缘缓缓落定。嘴边短促的白色呼气形先鼓起，再缩散。','米褐竖木板墙占满后层，左下枕头外只有一线灰米床边。','拱窗冷白柔光从房内右侧照入，脸上明暗轻软；胸口保持均匀柔白遮映。','细轻呼吸与室外隔墙的低轰，床布轻微摩擦。',kind='state',phase='state',meaning='治疗中的闭眼呼吸与原格枕上姿态保留。',characters=['女主席'])
add('02_001',9,'16:9，双人中近景，青梅男盔面居画面左侧，青梅女居右，弯起的手肘横过中央；稍低机位固定，两人的肩与肘接触点同框。','青梅女目光从床边猛转向盔面，眉毛压成尖角，张口责问；她把上臂贴近身体，弯肘向左连捣两下。青梅男胸侧各吃一次短促顶撞，肩膀先缩、盔面随即下偏，手掌护向接触处。他痛叫后抬手张指试图解释，女仍盯紧他，嘴角绷着，第二次责问压在他的否认前沿；他的手停在胸前，防备她再顶。','两人之间窄隙露出米褐木墙，侧后深褐床柱伸出画幅。','右侧拱窗冷白光掠过金属盔边与女面颊，木墙反出柔暖灰。','两声闷短的肘撞衣料声，护胸时布料急折，盔件轻碰。',ja=['主席さんを治療してる間も、あんたこの部屋にいたの？！そんなに彼女の体が見たいの？！','いって…！違う！！ただ心配だったんだ！'],tone='女由压怒责问升到第二句逼问；男先痛叫，再急促否认，最后把理由说完整。',kind='mixed',meaning='女弯肘捣男胸侧，男吃痛否认；责问与接触连续。',card={'opening':'治疗被男仍留在房内的事实打断。','beats':['女转头压眉，肘向胸侧捣两下','男缩肩护胸，痛叫后张手解释','女目光不松，男护手停在胸前'],'coupling':'每次顶肘有短促受力反应，解释从吃痛的气息中挤出。','landing':'二人仍近距离对峙，门响将夺走注意。'})
add('02_002',1.5,'16:9，贴近木地板的门脚特写，门板从画面中央向左斜开，右侧门缝形成纵深；固定机位。','门板缓慢向房内推进，底沿扫过地板上斜长亮带，门缝随之加宽；来者的短声从门后传入，光带跨过第一道板缝。','灰褐木地板、深褐门框与门板内侧，门外浅冷灰亮色在缝内铺开。','门外冷白环境光落成斜带，室内木面暗一档。','门轴拖长的轻吱声，门底擦过木板的一点沙响。',ja=['おや、ん？'],tone='门外来者先意外地出声，句尾抬起。',kind='mixed',meaning='门被推开，门外声音先到，身份保持未知。',characters=['门口来者'])
